import java.util.Arrays;
class GymMember {private String id;protected int sessions;private int[] fees=new int[10];private int count;public GymMember(String id,int fee){if(id==null||id.trim().length()<4||fee<=0)throw new IllegalArgumentException();this.id=id;}protected void chargeLateFee(int amount){if(amount<=0||count>=10)throw new IllegalArgumentException();fees[count++]=amount;}public int[] getLateFeeHistory(){return Arrays.copyOf(fees,count);}public int getTotalLateFees(){return Arrays.stream(fees,0,count).sum();}public void attendSession(){sessions++;}public int getSessionsAttended(){return sessions;}public String displayInfo(){return "Standard | Sessions: "+sessions;}}
class PremiumMember extends GymMember {String trainer;public PremiumMember(String id,int fee,String t){super(id,fee);trainer=t;}@Override protected void chargeLateFee(int amount){super.chargeLateFee(amount/2);}@Override public String displayInfo(){return "Premium | Trainer: "+trainer+" | Sessions: "+sessions;}}
public class Problem3_PremiumLateFeeLedger {public static void main(String[]x){PremiumMember p=new PremiumMember("MEM5",2000,"Coach Riya");p.chargeLateFee(200);int[] h=p.getLateFeeHistory();h[0]=999;System.out.println(p.getTotalLateFees());System.out.println(Arrays.toString(p.getLateFeeHistory()));}}